for (const line of notes.trim().split('\n')) {
  if (line.startsWith('@')) { week=Number(line.slice(1)); weeklyWordNotes[week]={}; continue; }
  const [terms, note]=line.split('|');
  for (const term of terms.split(',')) weeklyWordNotes[week][term]=note;
}

